// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 6.28318; 
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- CODICE SHADER ---

// Inizializziamo il tempo leggendolo dal buffer della GPU
float t = ubuf.u_time; 

// Costanti ottimizzate
float velocita = 0.5;  
// FIX: Altezza ridotta per non far sbattere la mesh contro la telecamera (W=4.0 e Z=4.0)
float altezza4D = 1.5; 

float r = 0.4;  

// Escursione massima di lift4D ora è 3.2 (rimane sempre < 4.0!)
float lift4D = (sin(t * velocita) + 1.0) * (altezza4D * 2.0); 

// --- 1. CURVA CENTRALE (Nodo a Otto) ---
float cx = (2.5 + cos(2.0 * u)) * cos(3.0 * u);
float cy = (2.5 + cos(2.0 * u)) * sin(3.0 * u);
float cz = 1.2 * sin(4.0 * u);
float cw = lift4D * sin(2.0 * u); 

vec3 Curve = vec3(cx, cy, cz);

// --- 2. DERIVATA (Direzione della curva) ---
float dr = -2.0 * sin(2.0 * u);
vec3 dC = vec3(
    dr * cos(3.0 * u) - (2.5 + cos(2.0 * u)) * 3.0 * sin(3.0 * u),
    dr * sin(3.0 * u) + (2.5 + cos(2.0 * u)) * 3.0 * cos(3.0 * u),
    4.8 * cos(4.0 * u)
);
vec3 Tangent = normalize(dC);

// --- 3. COSTRUZIONE DEL FRAME ---
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = cross(Tangent, Up);

if (length(Binorm) < 0.001) {
    Binorm = cross(Tangent, vec3(0.0, 1.0, 0.0));
}
Binorm = normalize(Binorm);

vec3 Norm = cross(Binorm, Tangent);
Norm = normalize(Norm);

// --- 4. COSTRUZIONE DEL TUBO ---
float tube_cos = r * cos(v);
float tube_sin = r * sin(v);

vec3 pos3D = Curve + (tube_cos * Norm + tube_sin * Binorm);

// Output finale
return vec4(pos3D * 0.35, cw);

