// Title: Neptune Racing (Audio)
// Author: Dave_Hoskins
// Source: https://www.shadertoy.com/view/XtX3Rr
// License: CC BY-NC-SA 3.0 (Shadertoy Default License)
//
// Note: Adapted for Desktop GLSL Audio. The original texture-based 
//       hash (iChannel0) has been replaced with a math-based pseudo-random hash.
// =========================================================================
// =========================================================================
// Adattamento per Desktop GLSL Audio
// Rimosse le dipendenze da iChannel0 (texture Shadertoy) in favore di 
// funzioni hash puramente matematiche per la compatibilità con il custom synth.
// =========================================================================

vec3 CameraPath( float t )
{
    float s = smoothstep(0.0, 3.0, t);
    vec3 pos = vec3( t*30.0*s +120.0, 1.0, t* 220.0* s -80.0);

    float a = t/4.0;
    pos.xz += vec2(1350.0 * cos(a), 350.0*sin(a));
    pos.xz += vec2(1400.0 * sin(-a*1.8), 400.0*cos(-a*4.43));

    return pos;
}

// -------------------------------------------------------------------------
// NUOVO HASH MATEMATICO: Sostituisce la lettura da iChannel0
vec2 Hash(vec2 p) 
{
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453123);
}

//--------------------------------------------------------------------------
vec2 Noise( in vec2 x )
{
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f*f*(3.0-2.0*f);

    // Ora utilizza la funzione Hash matematica definita sopra
    vec2 res = mix(mix( Hash(p + 0.0), Hash(p + vec2(1.0, 0.0)), f.x),
                   mix( Hash(p + vec2(0.0, 1.0) ), Hash(p + vec2(1.0, 1.0)), f.x), f.y);
    return res - 0.5;
}

//--------------------------------------------------------------------------
vec2 FBM( vec2 p )
{
    vec2 f;
    f  = 0.50000 * Noise(p); p = p * 2.32;
    f += 0.25000 * Noise(p); p = p * 2.23;
    f += 0.12500 * Noise(p); p = p * 2.31;
    f += 0.06250 * Noise(p); p = p * 2.28;
    f += 0.03125 * Noise(p);
    return f;
}

//--------------------------------------------------------------------------
// Funzione extra adattata anch'essa senza texture (anche se non usata sotto)
float rockets(float t)
{
    vec2 h1 = Hash(vec2(t*0.3, t*0.1731));
    vec2 h2 = Hash(vec2(t*0.2, t*0.01731));
    return (h1.x - 0.5) + (h2.y - 0.5);
}

//--------------------------------------------------------------------------
vec2 mainSound( in int samp, float time )
{
    float gTime = (time + 135.0) * 0.25;
    vec3 ca = CameraPath(gTime);
    vec3 ct = CameraPath(gTime + 0.05);
    float f = length(ct - ca) * 0.1;

    vec2 audio;
    audio = FBM(vec2(gTime * 120.0, gTime * 1200.0)) * 5.0 * f;
    audio += FBM(vec2(gTime * 200.0 * f, gTime * 200.0)) * 4.5;
    audio *= 0.1;

    // float g = mod(f*gTime, 8.0);
    // audio *= g < 4.0 ? 1.0 : 0.0;

    // Applica fade-in e fade-out
    return audio * smoothstep(0.0, 2.0, time) * smoothstep(180.0, 170.0, time);
}
//SOUND_END

// =========================================================================
// Title: Raymarching Basic
// Author: gyabo
// Source: https://www.shadertoy.com/view/Ml2XRD
//
// License: CC BY-NC-SA 3.0 (Shadertoy Default)
//          https://creativecommons.org/licenses/by-nc-sa/3.0/
//
// Attributions & Credits:
// - Includes a shading/color tweak suggested by Shadertoy user 'Shane'.
//
// Description:
// A compact and classic raymarching implementation featuring an infinite, 
// procedurally generated geometric landscape. It uses modulo arithmetic 
// on Signed Distance Fields (SDFs) to repeat the structure and features 
// a continuously rotating camera.
// =========================================================================

float map(vec3 p) {
	vec3 n = vec3(0, 1, 0);
	float k1 = 1.9;
	float k2 = (sin(p.x * k1) + sin(p.z * k1)) * 0.8;
	float k3 = (sin(p.y * k1) + sin(p.z * k1)) * 0.8;
	float w1 = 4.0 - dot(abs(p), normalize(n)) + k2;
	float w2 = 4.0 - dot(abs(p), normalize(n.yzx)) + k3;
	float s1 = length(mod(p.xy + vec2(sin((p.z + p.x) * 2.0) * 0.3, cos((p.z + p.x) * 1.0) * 0.5), 2.0) - 1.0) - 0.2;
	float s2 = length(mod(0.5+p.yz + vec2(sin((p.z + p.x) * 2.0) * 0.3, cos((p.z + p.x) * 1.0) * 0.3), 2.0) - 1.0) - 0.2;
	return min(w1, min(w2, min(s1, s2)));
}

vec2 rot(vec2 p, float a) {
	return vec2(
		p.x * cos(a) - p.y * sin(a),
		p.x * sin(a) + p.y * cos(a));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    float time = iTime;
	vec2 uv = ( fragCoord.xy / iResolution.xy ) * 2.0 - 1.0;
	uv.x *= iResolution.x /  iResolution.y;
	vec3 dir = normalize(vec3(uv, 1.0));
	dir.xz = rot(dir.xz, time * 0.23);dir = dir.yzx;
	dir.xz = rot(dir.xz, time * 0.2);dir = dir.yzx;
	vec3 pos = vec3(0, 0, time);
	vec3 col = vec3(0.0);
	float t = 0.0;
    float tt = 0.0;
	for(int i = 0 ; i < 100; i++) {
		tt = map(pos + dir * t);
		if(tt < 0.001) break;
		t += tt * 0.45;
	}
	vec3 ip = pos + dir * t;
	col = vec3(t * 0.1);
	col = sqrt(col);
	fragColor = vec4(0.05*t+abs(dir) * col + max(0.0, map(ip - 0.1) - tt), 1.0); //Thanks! Shane!
    fragColor.a = 1.0 / (t * t * t * t);
}
